# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">AKARSU AŞINIM VE BİRİKİM ŞEKİLLERİ İLE TÜRKİYE\'DEN ÖRNEKLER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">AKARSU AŞINIM ŞEKİLLERİ</text>\n  <text x="35" y="86" font-size="11" fill="#1e3a8a">• Vadiler: Çentik (Doğu Karadeniz), Boğaz (Geyve, Gülek),</text>\n  <text x="35" y="103" font-size="11" fill="#1e3a8a">  Kanyon (Köprülü, Ulubey), Geniş Tabanlı (Ege akarsuları)</text>\n  <text x="35" y="124" font-size="11" fill="#1e3a8a">• Dev Kazanı: Şelale tabanı (Manavgat, Düden, Muradiye)</text>\n  <text x="35" y="144" font-size="11" fill="#1e3a8a">• Peribacaları: Volkanik tüf + sel suları (Ürgüp-Göreme)</text>\n  <text x="35" y="164" font-size="11" fill="#1e3a8a">• Kırgıbayır (Badlands) ve Plato (Cihanbeyli, Haymana)</text>\n  <text x="35" y="184" font-size="11" fill="#1e3a8a">• Peneplen (Yontukdüz): Aşınımın son evresi</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">AKARSU BİRİKİM VE KARMA ŞEKİLLERİ</text>\n  <text x="370" y="86" font-size="11" fill="#14532d">• Birikinti Konisi ve Yelpazesi: Dağ eteği (Aydın, Bursa)</text>\n  <text x="370" y="106" font-size="11" fill="#14532d">• Dağ İçi Ovası: Erzincan, Iğdır, Malatya ovaları</text>\n  <text x="370" y="126" font-size="11" fill="#14532d">• Delta Ovası: Çukurova (Seyhan-Ceyhan), Bafra (Kızılırmak),</text>\n  <text x="370" y="143" font-size="11" fill="#14532d">  Çarşamba (Yeşilırmak), Menemen, Balat, Silifke</text>\n  <text x="370" y="164" font-size="11" font-weight="bold" fill="#166534">• Menderes (Büklüm) ve Seki (Taraça): Hem aşınım</text>\n  <text x="370" y="182" font-size="11" font-weight="bold" fill="#166534">  hem de birikim süreçlerinin birlikte görüldüğü şekillerdir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Türkiye\'de en geniş etki alanına sahip dış kuvvet akarsulardır; genç oluşumlu arazi vadileri derinleştirmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">RÜZGÂR VE BUZULLARIN OLUŞTURDUĞU YERYÜZÜ ŞEKİLLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">RÜZGÂR ŞEKİLLERİ (KURAK - YARI KURAK BÖLGE)</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Aşınım: Mantarkaya (Şeytan masası), Şahit tepe,</text>\n  <text x="35" y="106" font-size="11.2" fill="#713f12">  Yardang (oluklar), Tafoni (kovuklar) ve Hamada (çöl kaldırımı)</text>\n  <text x="35" y="130" font-size="11.2" fill="#713f12">• Birikim: Lös (ince toz birikimi), Kumul tepeleri ve</text>\n  <text x="35" y="148" font-size="11.2" fill="#713f12">  Barkan (hilal şekilli kumullar)</text>\n  <text x="35" y="172" font-size="11.2" font-weight="bold" fill="#854d0e">• Türkiye\'de: Konya-Karapınar, Tuz Gölü çevresi ve</text>\n  <text x="35" y="188" font-size="11.2" font-weight="bold" fill="#854d0e">  Güneydoğu Anadolu\'da rüzgâr etkisi belirgindir.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">BUZUL ŞEKİLLERİ (SOĞUK İKLİM VE YÜKSEK DAĞLAR)</text>\n  <text x="370" y="88" font-size="11.2" fill="#164e63">• Aşınım: Sirk çanağı (buzul gölü), Buzul vadisi (U profili),</text>\n  <text x="370" y="106" font-size="11.2" fill="#164e63">  Asılı vadi, Hörgüçkaya ve Keskin sırtlar (Aret)</text>\n  <text x="370" y="130" font-size="11.2" fill="#164e63">• Birikim: Moren (buzultaş), Drumlin (balina sırtı tepe)</text>\n  <text x="370" y="148" font-size="11.2" fill="#164e63">  ve Sander düzlüğü (buzul önü ovası)</text>\n  <text x="370" y="172" font-size="11.2" font-weight="bold" fill="#155e75">• Türkiye\'de: Cilo (Buzul), Ağrı, Kaçkar, Erciyes, Aladağlar,</text>\n  <text x="370" y="188" font-size="11.2" font-weight="bold" fill="#155e75">  Bolkar ve Uludağ\'ın 2200 m üstü zirvelerinde görülür.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Orta kuşakta yer alan Türkiye\'de kıyılarda buzul şekli görülmez; buzullar yüksek zirvelerde etkilidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DALGA VE AKINTI ŞEKİLLERİ İLE TÜRKİYE\'DE KIYI TİPLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">DALGA AŞINIM VE BİRİKİM ŞEKİLLERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Aşınım: Falez (Yalıyar), aşınım düzlüğü, doğal köprü</text>\n  <text x="35" y="106" font-size="11.2" fill="#581c87">  (Antalya-Alanya ve Doğu Karadeniz kıyıları)</text>\n  <text x="35" y="128" font-size="11.2" fill="#581c87">• Birikim: Kumsal (Plaj), Kıyı oku ve Kıyı kordonu</text>\n  <text x="35" y="150" font-size="11.2" fill="#581c87">• Lagün (Deniz kulağı): Büyükçekmece, Küçükçekmece, Terkos</text>\n  <text x="35" y="172" font-size="11.2" fill="#581c87">• Tombolo (Saplı ada): Kapıdağ Yarımadası ve Sinop</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">TÜRKİYE\'DE GÖRÜLEN VE GÖRÜLMEYEN KIYI TİPLERİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Boyuna Kıyı: Karadeniz ve Akdeniz (Dağlar kıyıya paralel)</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Enine Kıyı: Ege kıyıları (Edremit - Kuşadası arası)</text>\n  <text x="370" y="132" font-size="11.2" fill="#7c2d12">• Ria Kıyı: İstanbul-Çanakkale Boğazları, Haliç, Menteşe</text>\n  <text x="370" y="154" font-size="11.2" fill="#7c2d12">• Dalmaçya: Finike-Kaş kıyıları | Limanlı: Büyükçekmece</text>\n  <text x="370" y="176" font-size="11.2" font-weight="bold" fill="#9a3412">• Görülmez: Fiyort, Skyer (Buzul) ve Haliç-Watt (Gelgit)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kıta sahanlığının (şelf alanının) sığ olduğu kıyılarda dalga biriktirmesi, derin olduğu kıyılarda aşındırma baskındır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
